(function(){if(window.__billdrCopilots)return;window.__billdrCopilots=1;function init(){var nav=document.querySelector('.copilots_nav');var wrap=document.querySelector('.copilots_cards');if(!nav||!wrap)return;var tabs=[].slice.call(nav.querySelectorAll('.copilots_tab'));var cards=[].slice.call(wrap.querySelectorAll('.copilots_card'));if(!tabs.length||!cards.length)return;function setActive(i){for(var t=0;t<tabs.length;t++){var on=(t===i);var tab=tabs[t];var lab=tab.querySelector('.copilots_tab-label');var dot=tab.querySelector('.copilots_tab-dot');tab.classList[on?'add':'remove']('is-active');if(lab)lab.classList[on?'add':'remove']('is-active');if(dot)dot.classList[on?'add':'remove']('is-active');tab.setAttribute('aria-selected',on?'true':'false');}}setActive(0);for(var i=0;i<tabs.length;i++){tabs[i].setAttribute('role','tab');tabs[i].setAttribute('tabindex','0');(function(idx){function go(){var c=cards[idx];if(!c)return;var y=c.getBoundingClientRect().top+window.scrollY-Math.round(window.innerHeight*0.25);window.scrollTo({top:y,behavior:'smooth'});}tabs[idx].addEventListener('click',go);tabs[idx].addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}});})(i);}if(!('IntersectionObserver' in window)){return;}var vis={};var io=new IntersectionObserver(function(es){for(var k=0;k<es.length;k++){var idx=cards.indexOf(es[k].target);if(idx<0)continue;vis[idx]=es[k].isIntersecting?es[k].intersectionRatio:0;}var best=-1,bv=0;for(var j=0;j<cards.length;j++){var v=vis[j]||0;if(v>bv){bv=v;best=j;}}if(best>=0)setActive(best);},{root:null,rootMargin:'-20% 0px -35% 0px',threshold:[0,0.25,0.5,0.75,1]});for(var m=0;m<cards.length;m++)io.observe(cards[m]);}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();